const COMBAT_RULES=[
['Turno e movimento','Cada turno você tem 1 Move Action (andar até MOVE x2 metros, ou MOVE casas) e 1 Ação. Dá para dividir o movimento: andar, atacar, andar de novo. Run é uma segunda Move Action, só se você já se moveu no turno. Nadar, escalar e pular com corrida custam 2 m de movimento por metro. Pular parado alcança metade da distância.'],
['Ações possíveis','Attack (ataque corpo a corpo ou à distância), Choke, Equip/Drop Shield, Get into a Vehicle, Get Up (levantar de Prone), Grab, Hold Action (guarda a ação para um gatilho), Human Shield, Reload (troca o carregador inteiro por um tipo de munição), Run, Start a Vehicle (pula para o topo da iniciativa), Stabilize, Throw, Use NET Actions, Use an Object, Use a Skill, Vehicle Maneuver. Sacar uma arma de fácil acesso ou largar uma arma no chão não gasta Ação, mas guardar a arma gasta.'],
['ROF e divisão de ataques','Ataques com ROF 2 podem ser divididos pelo movimento (andar, atirar, andar, atirar) ou entre duas armas ROF 2. Ninguém faz mais de dois Attack Checks por Ação, e não dá para atacar com duas armas ROF 1 na mesma Ação, mesmo empunhando as duas. Ataques ROF 1 gastam a Ação inteira, mas ainda dá para dividir o movimento em volta deles.'],
['Ataque à distância','REF + perícia da arma + 1d10 contra o DV da tabela de distância. Quem tem REF 8 ou mais pode tentar esquivar (DEX + Evasion + 1d10) em vez de usar a tabela. Superar o DV acerta; empate favorece o defensor. A armadura reduz o dano.'],
['Tiro mirado','Gasta a Ação inteira (ROF máximo 1) e dá -8 no teste. Cabeça: o dano que passa pela armadura da cabeça é multiplicado por 2. Item na mão: se 1 ponto de dano passar pela armadura do corpo, o alvo derruba um item à sua escolha. Perna: se 1 ponto passar, o alvo sofre Broken Leg (se ainda tiver uma perna sem quebrar).'],
['Autofire','Gasta uma Ação e 10 balas (sem 10 balas no carregador não dá para usar). Use a perícia Autofire e a tabela de DV do Autofire. Não pode ser mirado, e quem tem REF 8+ ainda pode esquivar. Se acertar, role 2d6 e multiplique pelo quanto superou o DV, até o máximo da arma (3 para SMG, 4 para Assault Rifle). Dois 6 nos dados causam Critical Injury.'],
['Suppressive Fire','Gasta uma Ação e 10 balas (Autofire (3) ou (4) na arma). Todos a pé em 25 m, fora de cobertura e na sua linha de visão rolam WILL + Concentration + 1d10 contra o seu REF + Autofire + 1d10. Quem falha precisa usar a próxima Move Action para ir à cobertura (e a Run se não bastar).'],
['Shotgun Shell','Em vez de Slug, a escopeta pode disparar Shotgun Shell: um ataque (REF + Shoulder Arms + 1d10) contra DV13, sem tiro mirado. Se acertar, todos à sua frente a até 6 m que você veja sofrem 3d6 (um único teste de dano para todos). Quem tem REF 8+ pode esquivar individualmente.'],
['Arrows','Arcos e bestas não precisam de Reload, porque carregar a flecha faz parte do ataque. Flechas básicas sempre podem ser recuperadas depois de disparadas.'],
['Explosivos','Todo explosivo causa dano a todos (e ao cenário) numa área de 10 x 10 m centrada no alvo (um quadrado de 2 x 2 m, não uma pessoa). O dano é rolado uma vez. Se você errar o DV, o Mestre decide onde a bomba caiu dentro dessa área e a explosão acontece ali. Quem tem REF 8+ pode esquivar rolando mais que o seu teste original e sair da área. Quem está atrás de cobertura que o dano não destruiria não sofre dano; se o dano destruir a cobertura, a pessoa sofre o dano inteiro.'],
['Corpo a corpo','DEX + perícia da arma + 1d10 contra DEX + Evasion + 1d10 do defensor. Alcance de 2 m. ROF 2 (Very Heavy Melee Weapon tem ROF 1). Armas corpo a corpo tratam a armadura do defensor como metade do SP, arredondada para cima (SP11 vira SP6, e 5 de dano passam).  Uma arma de duas mãos pode ser usada com uma mão por quem tem BODY 8+. O tipo da arma define o dano.'],
['Brawling','Usa a perícia Brawling, com dano que depende do BODY: 1d6 (BODY 4 ou menos), 2d6 (5 a 6, ou até 4 com Cyberarm), 3d6 (7 a 10) e 4d6 (11+). Com um Cyberarm o dano é de pelo menos 2d6. Brawling não ignora metade da armadura. Também é a perícia de Grab.'],
['Grab, Choke e Throw','Grab: você e o alvo rolam DEX + Brawling + 1d10; se vencer, agarra o alvo ou toma um objeto das mãos dele. Quem está em Grapple sofre -2 em todas as Ações, e o agarrado não usa a Move Action e é arrastado. Choke: causa seu BODY direto nos HP (ignora armadura, sem ablação); se isso levaria um alvo com mais de 1 HP abaixo de 0, ele fica com 1 HP e Unconscious; 3 rodadas seguidas de Choke deixam inconsciente. Throw: derruba o agarrado (Prone), causando seu BODY direto nos HP. Arremessar objeto: ataque DEX + Athletics + 1d10 até 25 m, usando o DV do Grenade Launcher. Para quebrar um Grapple, quem está agarrado precisa vencer um Grab contra o atacante.'],
['Martial Arts','Dano pelo BODY (como Brawling), mas a armadura do alvo conta como metade do SP (arredondada para cima). Ataque com ROF 2: DEX + perícia da forma + 1d10 contra DEX + Evasion + 1d10 do alvo (ou um DV, em alguns Special Moves). Você precisa de pelo menos 1 ponto na forma para usá-la. Todas as formas têm Recovery (DV13: o Get Up não gasta Ação). Aikido: Disarming Combination (acertou Brawling e Martial Arts no mesmo alvo; DV15: ele perde um objeto das mãos) e Grab Escape (acertou 2 ataques corpo a corpo em quem te agarra; DV15: você se solta e ele sofre Broken Arm). Judo: Iron Grip (alvo agarrado; DV15: -2 extra para escapar e ele não faz ataques à distância) e Counter Throw (esquivou todos os ataques corpo a corpo; DV15: arremessa quem você esquivou, sem agarrar). Karate: Armor Breaking Combination (acertou arma corpo a corpo e Martial Arts; DV15: a armadura do alvo perde mais 2 de SP) e Bone Breaking Strike (WILL 8+; em vez dos 2 ataques; se acertar causa Broken Ribs). Taekwondo: Pressure Point Strike (WILL 8+; causa Spinal Injury, ou Brain Injury mirando a cabeça com -8) e Flying Kick (MOVE 8+, tendo andado 4 m; o alvo fica Prone e cai de moto). Detalhes nas páginas 178 a 180 do livro.'],
['Cobertura','Você está em cobertura se estiver totalmente atrás de algo que pare balas e o atacante não tiver linha de visão. Não existe cobertura parcial. Cada trecho de 2 x 2 m da cobertura tem HP e pode ser atacado; em 0 HP ela é destruída, e o excesso de dano se perde (não atinge quem está atrás). Cobertura Steel não sofre dano de Martial Arts ou Brawling, exceto de quem tem Cyberarm ou BODY 10+.'],
['Escudos','Equipar e largar um escudo gasta uma Ação. Um escudo com HP restante conta como cobertura móvel. Ao ser atacado por alguém que você vê, você pode interpor o escudo: não pode esquivar, mas o ataque ainda pode errar, e o escudo recebe o ataque inteiro nos HP. Bulletproof Shield tem 10 HP (100eb). Um corpo usado como escudo tem HP igual ao BODY que tinha em vida.'],
['Human Shield','Se você é o atacante de um Grapple e não usa outro escudo, uma Ação equipa o agarrado como Human Shield. Conta como cobertura, mas não bloqueia ataques corpo a corpo nem tiros mirados na cabeça. O escudo humano não esquiva e sofre o dano normalmente. Se morrer, vira um escudo com HP igual ao BODY.'],
['Armadura','O SP do local atingido é subtraído do dano. O que sobra tira HP e, se algum dano passou, a armadura daquele local perde 1 de SP (ablação) até ser consertada. Todas as armaduras do local são ablacionadas juntas. O SP não soma: vale a maior fonte de cada local. Armaduras pesadas dão penalidade em REF, DEX e MOVE (só a maior, uma vez). Se o MOVE chegar a 0, o personagem fica imóvel. Fogo e veneno ignoram armadura.'],
['Fogo, afogamento e asfixia','On Fire: até gastar uma Ação para apagar, você sofre dano direto nos HP no fim do seu turno (sem ablação): Mild 2 (fogueira), Strong 4 (gasolina), Deadly 6 (termite). Afogamento: dá para prender o fôlego por BODY minutos; depois disso, no início do turno você sofre seu BODY direto nos HP, ignorando armadura. Asfixia segue a mesma regra.']
];
const RANGE_NOTE='Linha: tipo da arma. Coluna: distância até o alvo. N/A: fora de alcance.';
const RULES=[
['Teste de perícia','Some o atributo ligado à perícia + o nível da perícia + 1d10 e compare com o DV. Você precisa superar o DV: em empate, o defensor vence. Num teste oposto, o DV é o resultado do oponente (atributo + perícia + 1d10). Um 10 natural no d10 manda rolar outro d10 e somar (crítico); um 1 natural manda rolar outro d10 e subtrair (falha crítica).'],
['Dificuldade (DV)','Simple 9 · Everyday 13 · Difficult 15 · Professional 17 · Heroic 21 · Incredible 24 · Legendary 29.'],
['Iniciativa e turno','Iniciativa = REF + 1d10. A ordem vai do maior para o menor, e cada rodada dura cerca de 3 segundos. No seu turno você tem 1 Move Action (andar até MOVE x2 metros, ou MOVE casas) e 1 Ação (atacar, usar perícia, recarregar, estabilizar, agarrar, etc.). Você pode dividir o movimento em volta da Ação.'],
['Ataque','Ataque à distância: REF + perícia da arma + 1d10 contra o DV da distância. Corpo a corpo: DEX + perícia da arma + 1d10 contra a defesa do alvo (Evasion). Ataques com ROF 2 podem ser divididos; ninguém faz mais de dois ataques por Ação.'],
['Pontos de vida','HP = 10 + 5 x (média de BODY e WILL, arredondada para cima). Seriously Wounded começa abaixo de metade do HP (arredondado para cima). Humanity = EMP x 10; sempre que a dezena de Humanity cai, o EMP cai junto.'],
['Dano e armadura','Subtraia o SP do local atingido do dano. O que passar tira HP, e a armadura daquele local perde 1 de SP (ablação) se algum dano passou. Fogo e veneno ignoram armadura. Armaduras pesadas dão penalidade em REF, DEX e MOVE (aplica-se só uma vez, a maior). O SP não soma: vale só o maior de cada local.'],
['Estados de ferimento','Lightly Wounded: menos que o HP máximo, sem efeito (estabilização DV10). Seriously Wounded: -2 em todas as Ações (DV13). Mortally Wounded: -4 em todas as Ações, -6 em MOVE (mínimo 1), faz Death Save a cada turno e sofre Critical Injury a cada dano (DV15 para voltar a 1 HP). Dead: um Death Save falho.'],
['Death Save','No início de cada turno em Mortally Wounded, role 1d10 somando a Death Save Penalty. Se o resultado for menor que o seu BODY você vive; um 10 sempre falha. A cada Death Save a penalidade sobe 1, e só volta ao valor base quando você é estabilizado com 1 HP.'],
['Critical Injury','Se dois ou mais dados de dano de um ataque corpo a corpo ou à distância caírem em 6, é um Critical Injury: role 2d6 na tabela do corpo (ou da cabeça, se foi tiro mirado na cabeça), repetindo se o alvo já tiver aquele ferimento. Causa 5 de dano bônus direto nos HP, sem ablação, mesmo que o dano não tenha passado o SP.'],
['Luck','Você tem uma reserva de pontos igual ao seu LUCK. Pode gastar pontos para somar ao resultado de um teste (1 ponto = +1). A reserva volta ao máximo no início da próxima sessão.']];

/* ---------------- cálculos ---------------- */
const stBase=(c,k)=>+((c.stats||{})[k])||0;
const hpMax=c=>10+5*Math.ceil((stBase(c,'BODY')+stBase(c,'WILL'))/2);
const humMax=c=>stBase(c,'EMP')*10;
const humCur=c=>c.humAtual==null?humMax(c):+c.humAtual;
const empCur=c=>clamp(Math.floor(humCur(c)/10),0,stBase(c,'EMP'));
const luckMax=c=>stBase(c,'LUCK');
const luckCur=c=>clamp(luckMax(c)-(+c.luckUsada||0),0,luckMax(c));
const armPen=c=>Math.max(0,...['head','body'].map(k=>+((c.armor||{})[k]||{}).pen||0));
const drugOn=(c,n)=>!!(c.drogas||{})[n],addicted=(c,n)=>(c.vicios||[]).includes(n);
function drugMod(c,k){let m=0;
 if(k==='INT'){if(drugOn(c,'Boost'))m+=2;if(addicted(c,'Boost'))m-=2}
 if(k==='REF'){if(drugOn(c,'Synthcoke'))m+=1;else if(addicted(c,'Synthcoke'))m-=2;if(!drugOn(c,'Black Lace')&&addicted(c,'Black Lace'))m-=2}
 return m}
const cwBorg=x=>{const e=cwBy(x.n);return !!e&&e[1]==='Borgware'};
const humCap=c=>humMax(c)-(c.cw||[]).reduce((a,x)=>a+(x.hl>0?(cwBorg(x)?4:2):0),0);
function psyTxt(c){const e=empCur(c);if(e>=3)return '';if(e===0&&humCur(c)<0)return PSY_X;return (PSY.find(x=>x[0]===e)||[0,''])[1]}
function wound(c){const hp=+c.vidaAtual,m=hpMax(c);return hp<=0?'mortal':hp<Math.ceil(m/2)?'serio':hp<m?'leve':'ok'}
const WOUND_TXT={ok:'Saudável',leve:'Lightly Wounded',serio:'Seriously Wounded (-2 em tudo)',mortal:'Mortally Wounded (-4 em tudo, -6 MOVE)'};
const woundPen=c=>({serio:drugOn(c,'Black Lace')?0:2,mortal:4}[wound(c)]||0);
function stEff(c,k){let v=(k==='EMP'?empCur(c):stBase(c,k))+drugMod(c,k);if(['REF','DEX','MOVE'].includes(k))v-=armPen(c);if(k==='MOVE'&&wound(c)==='mortal')v-=6;return Math.max(k==='MOVE'?1:0,v)}
const skLv=(c,n,spec)=>{const s=(c.skills||[]).find(x=>x.n===n&&(spec==null||x.spec===spec));return s?+s.l||0:0};
const calc=c=>({vida:hpMax(c),ini:stBase(c,'REF'),hum:humMax(c)});
const iniRoll=c=>stEff(c,'REF')+(c.role==='Solo'?(+((c.ca||{}).ir)||0):0)+d10();

/* ---------------- rolagens ---------------- */
let rmod=0,rdv=0;
async function rollCheck(c,label,parts,dvOpt){
 const wp=woundPen(c),m=+rmod||0,dv=dvOpt==null?(+rdv||0):dvOpt;
 let r=d10(),ex=0,crit='';
 if(r===10){ex=d10();crit='e'}else if(r===1){ex=-d10();crit='f'}
 const base=parts.reduce((a,[,v])=>a+v,0)-wp+m,total=base+r+ex;
 const ok=dv?total>dv:null;
 const cls=crit==='e'?'e':crit==='f'?'f':ok==null?'':ok?'s':'f';
 const res=(ok==null?'':(ok?'Sucesso':'Falha')+' vs DV'+dv)+(crit==='e'?(ok==null?'':' · ')+'crítico (+d10)':crit==='f'?(ok==null?'':' · ')+'falha crítica (−d10)':'');
 const expr=parts.map(([n,v])=>n+' '+v).join(' + ')+' + d10 ('+r+(ex?(ex>0?' +':' −')+Math.abs(ex):'')+')'+(wp?' − ferido '+wp:'')+(m?(m>0?' + mod ':' − mod ')+Math.abs(m):'');
 await post(c,label,{kind:'red',total,res,cls,expr,fx:crit});
 return {total,ok,dv,crit}}
const statParts=(c,k)=>[[k,stEff(c,k)]];
function rollStat(c,k){return rollCheck(c,k,statParts(c,k))}
function rollSkill(c,n,spec){const s=sk(n);if(!s)return;const stat=s[1],lv=skLv(c,n,spec);
 const extra=[];
 if(c.role==='Nomad'&&MOTO_SK.includes(n))extra.push(['Moto',+c.rank||1]);
 if(c.role==='Solo'&&n==='Perception'&&+((c.ca||{}).td))extra.push(['Threat Detection',+c.ca.td]);
 if(c.role==='Tech'&&MK_SK.includes(n)&&+((c.mk||{}).field))extra.push(['Field Expertise',+c.mk.field]);
 if(SMASH_SK.includes(n)){if(drugOn(c,'Smash'))extra.push(['Smash',2]);if(addicted(c,'Smash'))extra.push(['Vício em Smash',-2])}
 return rollCheck(c,n+(spec?' ('+spec+')':''),[[stat,stEff(c,stat)],[n,lv],...extra])}
function parseDmg(x){const m=String(x||'').replace(/\s/g,'').match(/^(\d*)d(\d+)([+-]\d+)?$/i);if(!m)return null;return {n:+m[1]||1,s:+m[2],b:+m[3]||0}}
let rband=-1;
const isBrawl=w=>w&&w.virt;
const virtBrawl=c=>({n:'Brawling',k:'melee',skill:'Brawling',dmg:brawlDmg(c),rof:2,mag:0,notes:'Soco, chute e Grab. Não ignora metade da armadura.',virt:1});
const wAt=(c,i)=>i==='b'?virtBrawl(c):c.weapons[+i];
function bandDv(w,auto){const t=auto?AUTO_DV[w.rt]:RANGE_DV[w.rt];if(rband<0||!t)return null;const v=t[rband];return v==null?-1:v}
function spend(c,w,n){if(!(+w.mag>0))return true;const a=w.ammo==null?+w.mag:+w.ammo;if(a<n){alert('Munição insuficiente'+(n>1?' ('+n+' balas)':'')+'. Recarregue (uma Ação).');return false}w.ammo=a-n;save(c);return true}
async function rollAtk(c,w){const s=sk(w.skill),stat=w.k==='melee'?'DEX':(s?s[1]:'REF');
 if(w.k==='ranged'&&!spend(c,w,1))return;
 let dv=null;if(w.k==='ranged'){dv=bandDv(w,0);if(dv===-1){alert('Fora de alcance para esta arma.');return}}
 const parts=[[stat,stEff(c,stat)],[w.skill,skLv(c,w.skill)]];if(w.q==='Excellent')parts.push(['Excellent',1]);
 if(c.role==='Solo'){const pa=clamp(Math.floor((+((c.ca||{}).pa)||0)/3),0,3);if(pa)parts.push(['Precision Attack',pa])}
 const r=await rollCheck(c,w.n+' (ataque)',parts,dv);
 if(r.crit==='f'&&w.q==='Poor')note('Arma Poor Quality: a falha crítica travou a arma. Gaste uma Ação para desemperrar.');
 return r}
async function rollAuto(c,w){const dv=bandDv(w,1);if(rband>=0&&(dv==null||dv===-1)){alert('Autofire não alcança essa distância.');return}
 if(!spend(c,w,10))return;
 const r=await rollCheck(c,w.n+' (Autofire)',[['REF',stEff(c,'REF')],['Autofire',skLv(c,'Autofire')]],dv==null?null:dv);
 if(r.dv&&r.total>r.dv){const m=Math.min(r.total-r.dv,w.af||3),a=1+Math.floor(Math.random()*6),b=1+Math.floor(Math.random()*6),tot=(a+b)*m,crit=a===6&&b===6;
  await post(c,w.n+' (dano Autofire)',{kind:'red',total:tot,res:crit?'CRITICAL INJURY! +5 de dano direto':'',cls:crit?'f':'',expr:'2d6 ['+a+', '+b+'] x '+m+' (superou o DV por '+(r.total-r.dv)+', máx. '+(w.af||3)+')',note:crit?'Role 2d6 na tabela de Critical Injury.':''})}
 else if(!r.dv)note('Compare o total com o DV; se acertar, role 2d6 x margem (máx. '+(w.af||3)+') com o botão Dano.')}
async function rollShell(c,w){if(!spend(c,w,1))return;
 const r=await rollCheck(c,'Shotgun Shell (ataque)',[['REF',stEff(c,'REF')],['Shoulder Arms',skLv(c,'Shoulder Arms')]],13);
 if(r.ok){const ds=[0,0,0].map(()=>1+Math.floor(Math.random()*6)),tot=ds.reduce((a,b)=>a+b,0),crit=ds.filter(x=>x===6).length>=2;
  await post(c,'Shotgun Shell (dano em área)',{kind:'red',total:tot,res:crit?'CRITICAL INJURY! +5 de dano direto':'',cls:crit?'f':'',expr:'3d6 ['+ds.join(', ')+'] em todos à frente, até 6 m',note:crit?'Role 2d6 na tabela de Critical Injury.':''})}}
async function rollDmg(c,w){const p=parseDmg(w.dmg);if(!p)return alert('Dano inválido: '+w.dmg);
 const ds=Array.from({length:p.n},()=>1+Math.floor(Math.random()*p.s)),tot=ds.reduce((a,b)=>a+b,0)+p.b,sixes=p.s===6?ds.filter(x=>x===6).length:0,crit=sixes>=2;
 await post(c,w.n+' (dano)',{kind:'red',total:tot,res:crit?'CRITICAL INJURY! +5 de dano direto':'',cls:crit?'f':'',expr:w.dmg+' ['+ds.join(', ')+']',note:(crit?'Role 2d6 na tabela de Critical Injury (corpo ou cabeça). ':'')+(w.k==='melee'&&!w.virt&&w.skill!=='Brawling'?'Arma corpo a corpo: a armadura do alvo conta como metade do SP (arredondada para cima).':'')})}
async function rollCrit(c,tab){const a=1+Math.floor(Math.random()*6),b=1+Math.floor(Math.random()*6),t=a+b,T=tab==='head'?CRIT_HEAD:CRIT_BODY,e=T.find(x=>x[0]===t);
 await post(c,'Critical Injury ('+(tab==='head'?'cabeça':'corpo')+')',{kind:'red',total:t,res:e[1],cls:'f',expr:'2d6 ['+a+', '+b+']',note:e[2]+' Tratamento: '+e[3]+'.'})}
async function rollDeath(c){const r=d10(),pen=+c.dsPen||0,body=stBase(c,'BODY'),ok=r!==10&&r+pen<body;c.dsPen=pen+1;if(!ok)c.morto=true;save(c);
 await post(c,'Death Save',{kind:'red',total:r+pen,res:ok?'Sobreviveu':'FALHOU: morte',cls:ok?'s':'f',expr:'d10 ('+r+')'+(pen?' + penalidade '+pen:'')+' contra BODY '+body+' (precisa ser menor; 10 sempre falha)'})}

/* ---------------- novo personagem (dados) ---------------- */
function blank(w){const stats={...w.stats};
 const skills=w.skills.map(s=>({n:s.n,spec:s.spec||'',l:s.l}));
 skills.push({n:'Language',spec:(w.lang||'Português').trim(),l:4});
 const armor={head:null,body:null},weapons=[],gear=[];
 const k=ROLES[w.role].kit;
 if(w.method!=='complete'){
  k.w.forEach((g,i)=>{const nm=g[0]==='*'?(w.kit['w'+i]||g[1]):g[0];const cat=[...MELEE,...RANGED].find(x=>x.n===nm);if(cat)weapons.push(mkWeapon(cat));else gear.push(nm)});
  k.g.forEach((g,i)=>{if(g.startsWith('*|')){const o=g.split('|').slice(1);gear.push(w.kit['g'+i]||o[0])}else gear.push(g)});
  const lj=ARMORS.find(a=>a.n==='Light Armorjack');armor.body={n:lj.n,sp:lj.sp,cur:lj.sp,pen:lj.pen};armor.head={n:lj.n,sp:lj.sp,cur:lj.sp,pen:lj.pen}}
 const cw=[];let hl=0;
 if(w.method!=='complete')(CW_KIT[w.role]||[]).forEach((g,i)=>{const nm=Array.isArray(g)?(w.kit['c'+i]||g[1]):g,x=cwBy(nm);if(x){cw.push({n:x[0],t:x[1],hl:x[4]});hl+=x[4]}});
 return {sys:'red',fv:2,player:w.jogador,role:w.role,rank:4,stats,skills,weapons,armor,cw,
  equip:gear.join('\n'),cyber:'',notes:'',vidaAtual:10+5*Math.ceil((stats.BODY+stats.WILL)/2),humAtual:Math.max(0,stats.EMP*10-hl),luckUsada:0,dsPen:0,
  eb:w.method==='complete'?2550:500,ip:0,metodo:w.method}}
const mkWeapon=x=>({n:x.n,k:x.k,skill:x.skill,dmg:x.dmg,rof:x.rof,mag:x.mag,ammo:x.mag,notes:x.ex||'',q:x.q||'',rt:RT[x.n]||'',af:AUTO_MAX[x.n]||0,shell:x.n==='Shotgun'?1:0});

/* ---------------- interface ---------------- */
const CSS=`.rd-st{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}
.rd-sc{background:var(--p2);border:1px solid var(--ln);padding:8px;text-align:center}
.rd-sc b{display:block;font:12px 'Special Elite','Courier New',monospace;color:var(--rd);letter-spacing:.1em}
.rd-sc input{width:56px;text-align:center;font-size:20px;margin:4px 0}
.rd-sc .mu{display:block;font-size:11px}
.rd-sc button{padding:2px 8px;font-size:12px}
.rd-sc.pen input{color:var(--ye)}
.rd-hp{display:flex;gap:6px;align-items:center;flex-wrap:wrap}
.rd-k{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}
.rd-sk{display:flex;align-items:center;gap:8px;padding:5px 0;border-bottom:1px solid var(--ln)}
.rd-sk .n{flex:1;min-width:0}.rd-sk .n small{color:var(--mu);margin-left:6px}
.rd-sk input[type=number]{width:52px;text-align:center}
.rd-sk .tt{width:34px;text-align:right;color:var(--ye);font:14px 'Special Elite',monospace}
.rd-sk.z{opacity:.55}
.rd-sk button{padding:3px 9px}
.rd-rb{display:flex;gap:10px;align-items:center;flex-wrap:wrap;background:var(--p2);border:1px solid var(--ln);padding:8px 10px;margin-bottom:10px}
.rd-rb input{width:64px}
.rd-w{display:grid;grid-template-columns:1fr auto;gap:6px 10px;align-items:center;background:var(--p2);border:1px solid var(--ln);padding:8px 10px;margin-bottom:8px}
.rd-w .c{display:flex;gap:6px;flex-wrap:wrap;align-items:center}
.rd-w input[type=number]{width:60px}
.rd-tbl{width:100%;border-collapse:collapse;font-size:13px}.rd-tbl td,.rd-tbl th{border-bottom:1px solid var(--ln);padding:6px 8px;text-align:left;vertical-align:top}
.rd-tag{font-size:11px;color:var(--mu)}
@media(max-width:700px){.rd-st{grid-template-columns:repeat(2,1fr)}.rd-w{grid-template-columns:1fr}}`;
(function(){const s=document.createElement('style');s.textContent=CSS;document.head.append(s)})();

const roleTag=c=>`${esc(c.role||'')} · Rank ${+c.rank||1}`;
function cardList(app){
 const M=isMaster(),list=chars.filter(vis);
 app.innerHTML=`<div class="row"><h2 class="sp">Personagens: ${list.length}</h2><button class="pr" data-a="novo">Novo personagem</button></div><br>
 <div class="grid">${list.map(c=>{const mx=hpMax(c),pv=clamp(100*(+c.vidaAtual||0)/mx,0,100);return `<div class="card"><div class="row"><div class="av">${avIn(c)}</div><div class="sp"><h3 style="margin:0">${esc(c.name)}</h3><div class="mu">${roleTag(c)}</div><div class="mu">Jogador: ${esc(c.player||'')}</div></div></div>
 <div class="bar"><i style="width:${pv}%"></i></div><div class="mu">HP ${c.vidaAtual} / ${mx} · ${WOUND_TXT[wound(c)].split(' (')[0]}</div>
 <div class="row" style="margin-top:8px"><button class="pr" data-o="${c.id}">Acessar ficha</button><span class="sp"></span>${c.morto?'<span class="tag hidt">morto</span>':''}${c.oculto?'<span class="tag hidt">oculto</span>':''}${canEdit(c)?`<button class="x" data-del="${c.id}" title="Excluir">✕</button>`:''}</div></div>`}).join('')||'<p class="mu">Nenhum personagem ainda. Crie o primeiro!</p>'}</div>`;
 app.onclick=async e=>{const b=e.target.closest('[data-a],[data-o],[data-del]');if(!b)return;const d=b.dataset;
  if(d.a==='novo'){wz=null;return go('novo')}
  if(d.o)return go('agentes',d.o);
  if(d.del&&await ask('Excluir este personagem? Isso não pode ser desfeito.')){if(await delRow('characters',d.del)){chars=chars.filter(x=>x.id!==d.del);render()}}}}

const opt=(v,t,sel)=>`<option value="${esc(v)}"${sel?' selected':''}>${esc(t)}</option>`;
function sheet(app){
 const c=chars.find(x=>x.id===open);if(!c||!vis(c)){open=null;return cardList(app)}
 const ed=canEdit(c),M=isMaster(),mx=hpMax(c),pv=clamp(100*(+c.vidaAtual||0)/mx,0,100),R=ROLES[c.role]||{ab:'',abd:''},dis=ed?'':' disabled';
 c.skills=c.skills||[];c.weapons=c.weapons||[];c.cw=c.cw||[];
 if(c.role==='Netrunner'&&!c.net)c.net={deck:'Cyberdeck',progs:[],hw:[]};if(c.net){c.net.progs=c.net.progs||[];c.net.hw=c.net.hw||[]}c.armor=c.armor||{head:null,body:null};
 const num=(f,v,extra)=>`<input type="number" data-f="${f}" value="${esc(v)}"${dis} ${extra||''}>`;
 const pen=armPen(c);
 const statHtml=STATS.map(([k,n])=>{const e=stEff(c,k),b=k==='EMP'?stBase(c,k):stBase(c,k);return `<div class="rd-sc${e!==b?' pen':''}" title="${esc(STAT_DESC[k])}"><b>${k}</b><span class="mu">${n}</span><input type="number" min="0" max="15" data-f="st:${k}" value="${b}"${dis}>${e!==b?`<span class="mu">efetivo ${e}</span>`:''}<br><button data-a="rs" data-k="${k}">🎲 ${k}</button></div>`}).join('');
 const rows=(cat)=>SKILLS.filter(s=>s[2]===cat).map(s=>{const [n,stat,,x2,needs]=s;
  const ent=c.skills.map((x,i)=>({x,i})).filter(o=>o.x.n===n);
  const line=(o,i)=>{const lv=o?+o.x.l||0:0,tot=stEff(c,stat)+lv;return `<div class="rd-sk${lv?'':' z'}" title="${esc(s[5])}"><span class="n">${esc(n)}${o&&o.x.spec?` <i>(${esc(o.x.spec)})</i>`:''}<small>${stat}${x2?' ×2':''}</small></span>${o?`<input type="number" min="0" max="10" data-f="sl:${o.i}" value="${lv}"${dis}>`:`<input type="number" min="0" max="10" data-f="sn:${esc(n)}" value="0"${dis}>`}<span class="tt">${tot}</span><button data-a="rk" data-n="${esc(n)}" data-s="${o?esc(o.x.spec||''):''}">🎲</button>${ed&&lv<10?`<button data-a="ipup" data-n="${esc(n)}" data-i="${o?o.i:-1}" title="Subir para o nível ${lv+1}: ${(x2?40:20)*(lv+1)} IP"${(+c.ip||0)>=(x2?40:20)*(lv+1)?'':' disabled'}>↑</button>`:''}${o&&needs&&ed?`<button class="x" data-a="sdel" data-i="${o.i}" title="Remover">✕</button>`:''}</div>`};
  if(needs)return ent.map(o=>line(o)).join('')+(ed?`<div class="rd-sk z"><span class="n">${esc(n)}<small>${stat}${x2?' ×2':''}</small></span><button data-a="sadd" data-n="${esc(n)}">+ adicionar</button></div>`:'');
  return line(ent[0]||null)}).join('');
 const skHtml=CATS.map(([cat,pt])=>{const has=c.skills.some(x=>(sk(x.n)||[])[2]===cat&&+x.l>0);return `<details class="xc"${has?' open':''}><summary><b>${pt}</b></summary><div style="padding:6px 12px">${rows(cat)}</div></details>`}).join('');
 const wRow=(w,i)=>`<div class="rd-w"><div><b>${esc(w.n)}</b>${w.q?` <span class="tag">${w.q}</span>`:''} <span class="rd-tag">${w.k==='melee'?'corpo a corpo':'à distância'} · ${esc(w.skill)} · ${esc(w.dmg)} · ROF ${w.rof}</span>${w.notes?`<div class="mu">${esc(w.notes)}</div>`:''}</div><div class="c"><button class="pr" data-a="atk" data-i="${i}">⚔ Atacar</button><button data-a="dmg" data-i="${i}">💥 Dano</button>${w.af?`<button data-a="auto" data-i="${i}" title="Gasta 10 balas e a Ação. Usa Autofire.">Autofire</button>`:''}${w.shell?`<button data-a="shell" data-i="${i}" title="DV13, 3d6 em área até 6 m">Shotgun Shell</button>`:''}${+w.mag>0?`<span class="mu">munição</span><input type="number" min="0" data-f="wa:${i}" value="${w.ammo==null?w.mag:w.ammo}"${dis}><button data-a="rel" data-i="${i}">Recarregar</button>`:''}${ed&&!w.virt?`<button class="x" data-a="wdel" data-i="${i}">✕</button>`:''}</div></div>`;
 const wHtml=wRow(virtBrawl(c),'b')+c.weapons.map((w,i)=>wRow(w,i)).join('');
 const armSel=k=>{const a=c.armor[k];return `<div class="row"><b style="width:70px">${k==='head'?'Cabeça':'Corpo'}</b><select data-f="ar:${k}"${dis}>${opt('','Sem armadura',!a)}${ARMORS.map(x=>opt(x.n,x.n+' (SP '+x.sp+')',a&&a.n===x.n)).join('')}</select>${a?`<span>SP <b>${a.cur}</b> / ${a.sp}</span><button data-a="abl" data-k="${k}">Ablação −1</button><button data-a="rep" data-k="${k}">Consertar</button>`:''}</div>`};
 app.innerHTML=`<div class="row"><button data-a="back">← Personagens</button><h2 class="sp">${esc(c.name)}</h2><span class="tag">${roleTag(c)}</span>${c.morto?'<span class="tag hidt">MORTO</span>':''}${M?`<button class="eye${c.oculto?' on':''}" data-a="oculto">${c.oculto?'Oculto dos jogadores':'Ocultar dos jogadores'}</button>`:''}</div><br>
 <div class="box"><h3>Identidade</h3><div class="row"><div class="av" style="cursor:${ed?'pointer':'default'}" data-a="foto">${avIn(c)}</div><input type="file" id="fotoIn" accept="image/*" hidden>
  <input data-f="name" value="${esc(c.name)}" placeholder="Nome"${dis} style="flex:1;min-width:140px"><input data-f="player" value="${esc(c.player||'')}" placeholder="Jogador"${dis} style="flex:1;min-width:120px">
  <select data-f="role"${dis}>${ROLE_NAMES.map(r=>opt(r,r,c.role===r)).join('')}</select><span class="mu">Rank</span>${num('rank',c.rank||1,'min="1" max="10" style="width:64px"')}
  <span class="mu">eb</span>${num('eb',c.eb||0,'style="width:90px"')}<span class="mu">IP</span>${num('ip',c.ip||0,'style="width:70px" title="Improvement Points"')}<span class="mu">Rep</span>${num('rep',c.rep||0,'min="0" max="10" style="width:60px" title="Reputation (0 a 10)"')}</div></div>
 <div class="box"><h3>Atributos</h3><div class="rd-st">${statHtml}</div>${pen?`<p class="mu">Penalidade de armadura: −${pen} em REF, DEX e MOVE.</p>`:''}</div>
 <div class="rd-k"><div class="box"><h3>Vida</h3><div class="bar"><i style="width:${pv}%"></i></div><div class="rd-hp"><b style="font-size:20px">${c.vidaAtual} / ${mx}</b><button data-a="hp" data-d="-5"${dis}>−5</button><button data-a="hp" data-d="-1"${dis}>−1</button><button data-a="hp" data-d="1"${dis}>+1</button><button data-a="hp" data-d="5"${dis}>+5</button><button data-a="hpfull"${dis}>Cheio</button></div>
  <p class="mu">${WOUND_TXT[wound(c)]} · Seriously Wounded abaixo de ${Math.ceil(mx/2)}</p>
  ${c.morto?`<p class="rd">Este personagem morreu (Death Save falhou).</p>${ed?'<button data-a="revive">Reviver (desfazer a morte)</button>':''}`:''}<div class="row"><button data-a="death">Death Save</button><span class="mu">penalidade ${+c.dsPen||0}, BODY ${stBase(c,'BODY')}</span><button data-a="dsreset"${dis}>Estabilizado</button></div></div>
 <div class="box"><h3>Humanity e sorte</h3><div class="row"><span>Humanity</span>${num('hum',humCur(c),'min="'+HUM_MIN+'" style="width:70px"')}<span class="mu">/ ${humMax(c)} (máx. com o cyberware atual: ${humCap(c)}) · EMP atual ${empCur(c)}</span></div>${psyTxt(c)?`<p class="rd">${esc(psyTxt(c))}</p>`:''}<div class="row" style="margin-top:8px"><button data-a="therapy"${ed?'':' disabled'}>Terapia</button><button data-a="trauma"${ed?'':' disabled'}>Trauma (perda de Humanity)</button></div>
  <div class="row" style="margin-top:8px"><span>Luck</span><b>${luckCur(c)} / ${luckMax(c)}</b><button data-a="luck"${dis}>Gastar 1</button><button data-a="luckreset"${dis}>Nova sessão</button></div></div>
 <div class="box"><h3>Armadura</h3>${armSel('head')}${armSel('body')}</div></div>
 <div class="box"><h3>Função: ${esc(c.role||'')} · ${esc(R.ab)} (Rank ${+c.rank||1})</h3><p>${esc(R.abd)}</p>${roleTools(c,ed,dis)}</div>
 <div class="box"><h3>Combate</h3><div class="row"><button class="pr" data-a="ini">Iniciativa (REF + 1d10)</button><button data-a="hit">Sofrer dano</button><button data-a="crit" data-t="body">Critical Injury: corpo</button><button data-a="crit" data-t="head">Critical Injury: cabeça</button>${ed?'<button data-a="wadd">+ Arma do catálogo</button>':''}</div><div class="rd-rb" style="margin-top:10px"><span>Distância do alvo</span><select id="rband">${opt('-1','Usar o DV da barra de perícias',rband<0)}${BANDS.map((n,i)=>opt(i,n,rband===i)).join('')}</select><span class="mu">Armas à distância usam o DV da tabela do tipo de arma.</span></div>${wHtml}</div>
 <div class="box"><h3>Perícias</h3><div class="rd-rb"><span>Modificador</span><input type="number" id="rmod" value="${rmod}"><span>DV</span><select id="rdv">${opt('0','Sem DV',!rdv)}${DVS.map(([n,v])=>opt(v,n+' ('+v+')',+rdv===v)).join('')}</select><span class="mu">Ferido: −${woundPen(c)} automático. O total é atributo + nível + 1d10.</span></div>${skHtml}</div>
 <div class="box"><h3>Cyberware instalado</h3>${c.cw.map((x,i)=>{const e=cwBy(x.n);return `<div class="rd-sk"><span class="n"><b>${esc(x.n)}</b><small>${esc(x.t)} · HL ${x.hl}</small>${e?`<div class="mu">${esc(e[6])}</div>`:''}</span>${ed?`<button class="x" data-a="cwdel" data-i="${i}" title="Remover (a Humanity perdida não volta)">✕</button>`:''}</div>`}).join('')||'<p class="mu">Nenhum cyberware instalado.</p>'}${ed?'<div class="row" style="margin-top:8px"><button data-a="cwadd">+ Instalar do catálogo</button></div>':''}
  <p class="mu">Perdeu Humanity: Humanity ${humCur(c)} / ${humMax(c)}. Cada 10 pontos perdidos tiram 1 de EMP.</p></div>
 ${c.net?netBox(c,ed,dis):''}
 <div class="box"><h3>Drogas e vícios</h3><p class="mu">Ao acabar a duração da droga, role o efeito secundário: se falhar, vira vício até terapia. Os efeitos de atributo e perícia já entram nas rolagens.</p>${DRUGS.map(x=>{const n=x[0],on=drugOn(c,n),ad=addicted(c,n);return `<div class="rd-w"><div><b>${n}</b> ${on?'<span class="tag">ativa</span>':''} ${ad?'<span class="tag hidt">viciado</span>':''}<div class="mu">${esc(x[4])} (dura ${x[2]})</div>${ad?`<div class="mu">Vício: ${esc(x[5])}</div>`:''}</div><div class="c">${ed?(on?`<button data-a="drugend" data-n="${n}">Fim do efeito (rolar DV${x[3]})</button>`:`<button data-a="drug" data-n="${n}">Tomar dose (${x[1]}eb)</button>`):''}</div></div>`}).join('')}</div>
 <div class="rd-k"><div class="box"><h3>Equipamento · ${c.eb||0}eb</h3>${ed?'<div class="row" style="margin-bottom:8px"><button data-a="buy">+ Comprar item</button></div>':''}<textarea data-f="equip" rows="6"${dis} style="width:100%">${esc(c.equip||'')}</textarea></div>
 <div class="box"><h3>Outros implantes e anotações de cyberware</h3><textarea data-f="cyber" rows="6"${dis} style="width:100%">${esc(c.cyber||'')}</textarea></div>
 <div class="box"><h3>Anotações</h3><textarea data-f="notes" rows="6"${dis} style="width:100%">${esc(c.notes||'')}</textarea></div></div>`;
 const redo=()=>{const y=scrollY,ae=document.activeElement;let sel=null;
  if(ae&&ae!==document.body&&app.contains(ae)){const a=ae.dataset;sel=a.f?'[data-f="'+a.f+'"]':a.a?'[data-a="'+a.a+'"]'+(a.i!=null?'[data-i="'+a.i+'"]':'')+(a.n!=null?'[data-n="'+a.n.replace(/"/g,'\\"')+'"]':''):ae.id?'#'+ae.id:null}
  sheet(app);scrollTo(0,y);if(sel){const n=app.querySelector(sel);if(n)n.focus({preventScroll:true})}};
 const upd=()=>{save(c);twRender&&twRender()};
 app.onclick=async e=>{const b=e.target.closest('[data-a]');if(!b)return;const d=b.dataset,a=d.a;
  if(a==='back')return go('agentes');
  if(a==='imp')return rollCheck(c,'Charismatic Impact',[['Rank',+c.rank||1]],+d.dv);
  if(a==='backup'){const r=d10(),rk=+c.rank||1,ok=r<=rk;return post(c,'Backup',{kind:'red',total:r,res:ok?'Reforços a caminho em '+(1+Math.floor(Math.random()*6))+' rodada(s)':'Ninguém atendeu',cls:ok?'s':'f',expr:'d10 ('+r+') contra Rank '+rk+' (tirar o Rank ou menos)'})}
  if(a==='haggle')return rollCheck(c,'Haggle',[['COOL',stEff(c,'COOL')],['Trading',skLv(c,'Trading')],['Rank',+c.rank||1]]);
  if(a==='rumor')return rumorPassive(c);
  if(a==='publish')return publishStory(c,+(($('#mev')||{}).value||0));
  if(a==='maker'){const v=await makerModal(c);if(v)await rollMaker(c,v);return}
  if(a==='surg')return rollCheck(c,'Cirurgia ('+d.n+')',[['TECH',stEff(c,'TECH')],['Surgery',Math.min(10,2*((c.med||{}).surg||0))]],+d.dv);
  if(a==='medtech')return rollCheck(c,'Sintetizar fármaco',[['TECH',stEff(c,'TECH')],['Medical Tech',Math.min(10,((c.med||{}).pharm||0)+((c.med||{}).cryo||0))]],13);
  if(a==='tmed'){const th=THERAPY[+d.i];await rollCheck(c,'Terapia: '+th[0],[['TECH',stEff(c,'TECH')],['Medical Tech',Math.min(10,((c.med||{}).pharm||0)+((c.med||{}).cryo||0))]],+th[2].slice(2));return note('Materiais: '+th[4]+'. Custo ao paciente: '+th[3]+'. Leva 1 semana.')}
  if(a==='tsave'){const m=c.team[+d.i],r=1+Math.floor(Math.random()*6),ok=r<m.loy;return post(c,'Loyalty Save: '+(m.n||'Team Member'),{kind:'red',total:r,res:ok?'Obedece':'Recusa, estraga ou trai',cls:ok?'s':'f',expr:'d6 ('+r+') contra Loyalty '+m.loy+' (precisa tirar menos)'})}
  if(a==='iface')return rollIface(c,d.n);
  if(a==='patk')return rollProg(c,c.net.progs[+d.i]);
  if(a==='pdmg')return rollDice(c,c.net.progs[+d.i].n+' (dano)',PDMG[c.net.progs[+d.i].n]);
  if(a==='rs')return rollStat(c,d.k);
  if(a==='rk')return rollSkill(c,d.n,d.s||undefined);
  if(a==='ini')return rollCheck(c,'Iniciativa',[['REF',stEff(c,'REF')],...(c.role==='Solo'&&+((c.ca||{}).ir)?[['Initiative Reaction',+c.ca.ir]]:[])],0);
  if(a==='death')return rollDeath(c).then(redo);
  if(a==='crit')return rollCrit(c,d.t);
  if(a==='atk')return rollAtk(c,wAt(c,d.i)).then(redo);
  if(a==='dmg')return rollDmg(c,wAt(c,d.i));
  if(a==='auto')return rollAuto(c,wAt(c,d.i)).then(redo);
  if(a==='shell')return rollShell(c,wAt(c,d.i)).then(redo);
  if(!ed)return;
  if(a==='hp'){c.vidaAtual=clamp((+c.vidaAtual||0)+(+d.d),0,hpMax(c));upd();return redo()}
  if(a==='revive'){c.morto=false;c.dsPen=0;if((+c.vidaAtual||0)<1)c.vidaAtual=1;upd();return redo()}
  if(a==='tadd'){const n=prompt('Nome do Team Member');if(!n)return;const j=prompt('Função (ex.: Company Bodyguard)')||'';c.team.push({n:n.trim(),job:j.trim(),loy:1+Math.floor(Math.random()*6)+1,notes:''});upd();return redo()}
  if(a==='tdel'){if(await ask('Remover este Team Member? A empresa o substitui na próxima sessão, por 200eb, com Loyalty 1.')){c.team.splice(+d.i,1);upd();redo()}return}
  if(a==='tend'){const gone=[];c.team=c.team.filter(m=>{m.loy=Math.min(10,m.loy);if(m.loy<0){gone.push(m.n);return false}return true});upd();if(gone.length)note('Saíram da empresa por Loyalty abaixo de 0: '+gone.join(', ')+'.');return redo()}
  if(a==='drug'){const n=d.n,dr=DRUGS.find(x=>x[0]===n);c.drogas=c.drogas||{};c.drogas[n]=true;c.eb=(+c.eb||0);
   if(n==='Black Lace'){const r=drugRoll(c,'2d6');c.blHL=(+c.blHL||0)+r.v;c.humAtual=Math.max(HUM_MIN,humCur(c)-r.v);upd();await post(c,'Black Lace: Humanity Loss',{kind:'red',total:r.v,res:'Humanity '+humCur(c)+' / '+humMax(c),cls:'f',expr:r.t+' (devolvida se você resistir ao efeito secundário)'})}else upd();
   note(n+': efeito primário ativo ('+dr[2]+').');return redo()}
  if(a==='drugend'){const n=d.n,r=await rollCheck(c,'Efeito secundário: '+n,[['WILL',stEff(c,'WILL')],['Resist Torture/Drugs',skLv(c,'Resist Torture/Drugs')]],DRUG_DV[n]);
   c.drogas[n]=false;c.vicios=c.vicios||[];
   if(!r.ok){if(!c.vicios.includes(n))c.vicios.push(n);note('Você falhou: agora é viciado em '+n+'.')}
   else if(n==='Black Lace'&&c.blHL){c.humAtual=Math.min(humMax(c),humCur(c)+c.blHL);note('Você resistiu: recuperou '+c.blHL+' de Humanity.')}
   if(n==='Black Lace')c.blHL=0;upd();return redo()}
  if(a==='therapy'){const t=await therapyModal(c);if(t){if(!confirm('A terapia deu certo (o Medtech passou no teste)?'))return;const th=THERAPY[t.i];
    if(t.i===0){c.vicios=(c.vicios||[]).filter(v=>v!==t.v);upd();note('Livre do vício em '+t.v+'. Por 1 ano, você falha automaticamente no efeito secundário dessa droga.')}
    else{const r=drugRoll(c,t.i===1?'2d6':'4d6'),cap=humCap(c),n=Math.max(humCur(c),Math.min(cap,humCur(c)+r.v));c.humAtual=n;upd();await post(c,'Terapia: '+th[0],{kind:'red',total:r.v,res:'Humanity '+humCur(c)+' / máx. '+cap,cls:'s',expr:r.t,note:humCur(c)>=cap?'O máximo cai com o cyberware instalado (2 por peça, 4 por borgware).':''})}
    redo()}return}
  if(a==='trauma'){const t=await traumaModal();if(t){const r=drugRoll(c,t[1]);c.humAtual=Math.max(HUM_MIN,humCur(c)-r.v);upd();await post(c,'Trauma: perda de Humanity',{kind:'red',total:r.v,res:'Humanity '+humCur(c)+' / '+humMax(c)+' (EMP '+empCur(c)+')',cls:'f',expr:r.t+' · '+t[0]});redo()}return}
  if(a==='hit'){const v=await hitModal(c);if(v){await applyHit(c,v);upd();redo()}return}
  if(a==='ipup'){const n=d.n,i=+d.i,e=sk(n),lv=i>=0?+c.skills[i].l||0:0,cost=(e[3]?40:20)*(lv+1);if((+c.ip||0)<cost)return alert('IP insuficientes: precisa de '+cost);c.ip-=cost;if(i>=0)c.skills[i].l=lv+1;else c.skills.push({n,spec:'',l:1});upd();return redo()}
  if(a==='rankup'){const rk=+c.rank||1,cost=60*(rk+1);if(rk>=10)return;if((+c.ip||0)<cost)return alert('IP insuficientes: precisa de '+cost);c.ip-=cost;c.rank=rk+1;upd();return redo()}
  if(a==='hpfull'){c.vidaAtual=hpMax(c);upd();return redo()}
  if(a==='dsreset'){c.dsPen=0;upd();return redo()}
  if(a==='luck'){c.luckUsada=clamp((+c.luckUsada||0)+1,0,luckMax(c));upd();return redo()}
  if(a==='luckreset'){c.luckUsada=0;upd();return redo()}
  if(a==='abl'){const x=c.armor[d.k];if(x&&x.cur>0){x.cur--;upd();redo()}return}
  if(a==='rep'){const x=c.armor[d.k];if(x){x.cur=x.sp;upd();redo()}return}
  if(a==='rel'){const w=c.weapons[+d.i];if(w){w.ammo=w.mag;upd();redo()}return}
  if(a==='wdel'){if(await ask('Remover esta arma?')){c.weapons.splice(+d.i,1);upd();redo()}return}
  if(a==='wadd'){const w=await pickWeapon();if(w){c.weapons.push(mkWeapon(w));upd();redo()}return}
  if(a==='sdel'){c.skills.splice(+d.i,1);upd();return redo()}
  if(a==='sadd'){const sp=prompt(SPEC_PICK[d.n]||'Especialização');if(sp&&sp.trim()){c.skills.push({n:d.n,spec:sp.trim(),l:1});upd();redo()}return}
  if(a==='cwadd'){const r=await pickCw();if(r){const x=r.x,rl=r.fixed?{v:x[4],t:'valor fixo (criação)'}:hlRoll(x);
    c.humAtual=Math.max(HUM_MIN,humCur(c)-rl.v);c.cw.push({n:x[0],t:x[1],hl:rl.v});upd();
    if(rl.v>0)await post(c,'Humanity Loss: '+x[0],{kind:'red',total:rl.v,res:'Humanity '+humCur(c)+' / '+humMax(c)+' (EMP '+empCur(c)+')',cls:'f',expr:rl.t});
    redo()}return}
  if(a==='cwdel'){if(await ask('Remover este cyberware? A Humanity perdida não volta.')){c.cw.splice(+d.i,1);upd();redo()}return}
  if(a==='buy'){const g=await pickGear();if(g){if(g.deduct)c.eb=(+c.eb||0)-g.c;c.equip=(c.equip?c.equip+'\n':'')+g.n;upd();if((+c.eb||0)<0)note('Atenção: suas eb ficaram negativas.');redo()}return}
  if(a==='netadd'){const r=await pickNet();if(r){if(r.k==='p'){const x=PROGRAMS[r.i];c.net.progs.push({n:x[0],bi:0,on:false,rez:x[4]})}else if(r.k==='b'){const x=BICE[r.i];c.net.progs.push({n:x[0],bi:1,on:false,rez:x[6]})}else c.net.hw.push(HARDWARE[r.i][0]);upd();redo()}return}
  if(a==='ptog'){const p=c.net.progs[+d.i];p.on=!p.on;upd();return redo()}
  if(a==='prez'){const p=c.net.progs[+d.i],e=p.bi?BICE.find(x=>x[0]===p.n):PROGRAMS.find(x=>x[0]===p.n),mx=p.bi?e[6]:e[4];p.rez=clamp((p.rez==null?mx:p.rez)+(+d.d),0,mx);upd();return redo()}
  if(a==='pdel'){c.net.progs.splice(+d.i,1);upd();return redo()}
  if(a==='hdel'){c.net.hw.splice(+d.i,1);upd();return redo()}
  if(a==='oculto'){c.oculto=!c.oculto;upd();return redo()}
  if(a==='foto')return $('#fotoIn').click()};
 const fi=$('#fotoIn');if(fi)fi.onchange=async e=>{const f=e.target.files[0];if(!f)return;try{c.foto=await fotoResize(f);upd();redo()}catch(er){alert(er.message)}};
 app.onchange=e=>{const t=e.target;
  if(t.id==='rband'){rband=+t.value;return}
  if(t.id==='rmod'){rmod=+t.value||0;return}if(t.id==='rdv'){rdv=+t.value||0;return}
  const f=t.dataset.f;if(!f||!ed)return;const v=t.value;
  if(f==='name'){c.name=v.trim()||c.name}
  else if(f==='player')c.player=v;
  else if(f==='role'){c.role=v;if(v==='Netrunner'&&!c.net)c.net={deck:'Cyberdeck',progs:[],hw:[]}}
  else if(f==='deck'){c.net.deck=v}
  else if(f==='rank')c.rank=clamp(+v||1,1,10);
  else if(f==='eb')c.eb=+v||0;else if(f==='ip')c.ip=+v||0;else if(f==='rep')c.rep=clamp(+v||0,0,10);
  else if(f.startsWith('ca:')){c.ca=c.ca||{};c.ca[f.slice(3)]=clamp(+v||0,0,10)}
  else if(f==='hum')c.humAtual=clamp(+v||0,HUM_MIN,humMax(c));
  else if(f.startsWith('mk:')){c.mk=c.mk||{};c.mk[f.slice(3)]=clamp(+v||0,0,10)}
  else if(f.startsWith('md:')){c.med=c.med||{ph:[]};const k=f.slice(3);c.med[k]=clamp(+v||0,0,5);c.med.ph=(c.med.ph||[]).slice(0,c.med.pharm||0)}
  else if(f.startsWith('ph:')){c.med=c.med||{ph:[]};const n=f.slice(3);c.med.ph=c.med.ph||[];if(t.checked){if(c.med.ph.length<(c.med.pharm||0)&&!c.med.ph.includes(n))c.med.ph.push(n)}else c.med.ph=c.med.ph.filter(x=>x!==n)}
  else if(f.startsWith('tn:')){c.team[+f.slice(3)].n=v}
  else if(f.startsWith('tj:')){c.team[+f.slice(3)].job=v}
  else if(f.startsWith('tt:')){c.team[+f.slice(3)].notes=v}
  else if(f.startsWith('tev:')){if(v!==''){const m=c.team[+f.slice(4)];m.loy+=LOYALTY[+v][1]}}
  else if(f.startsWith('st:')){const k=f.slice(3);c.stats[k]=clamp(+v||0,0,15);if(k==='EMP')c.humAtual=clamp(humCur(c),0,humMax(c));c.vidaAtual=clamp(+c.vidaAtual||0,0,hpMax(c))}
  else if(f.startsWith('sl:')){const s=c.skills[+f.slice(3)];if(s)s.l=clamp(+v||0,0,10)}
  else if(f.startsWith('sn:')){const n=f.slice(3),l=clamp(+v||0,0,10);if(l>0)c.skills.push({n,spec:'',l})}
  else if(f.startsWith('wa:')){const w=c.weapons[+f.slice(3)];if(w)w.ammo=clamp(+v||0,0,+w.mag)}
  else if(f.startsWith('ar:')){const k=f.slice(3),a=ARMORS.find(x=>x.n===v);c.armor[k]=a?{n:a.n,sp:a.sp,cur:a.sp,pen:a.pen}:null}
  else if(['equip','cyber','notes'].includes(f))c[f]=v;
  upd();if(!/^(name|player|eb|rep|equip|cyber|notes|wa:|ca:|tn:|tj:|tt:)/.test(f))setTimeout(redo,0)}}

