async function applyHit(c,v){const ar=(c.armor||{})[v.l];let dmg=v.d;
 if(v.f)dmg=Math.max(0,dmg-Math.min(5,Math.floor((+c.ca.dd||0)/2)));
 const sp=ar?+ar.cur:0,eff=v.i?0:(v.m?Math.ceil(sp/2):sp);
 let through=Math.max(0,dmg-eff);if(v.a&&v.l==='head'&&through>0)through*=2;
 let abl=0;if(!v.i&&ar&&dmg>eff&&!(v.m&&false)){abl=v.p?2:1;ar.cur=Math.max(0,ar.cur-abl)}
 const bonus=v.c?5:0,loss=through+bonus,old=+c.vidaAtual||0;c.vidaAtual=Math.max(0,old-loss);save(c);
 const w0=wound(c);
 await post(c,'Dano sofrido',{kind:'red',total:loss,res:c.vidaAtual<=0?'MORTALLY WOUNDED: Death Save a cada turno':(woundPen(c)?WOUND_TXT[w0].split(' (')[0]:''),cls:c.vidaAtual<=0?'f':'',expr:v.d+' de dano'+(v.f?' − deflexão':'')+' − SP '+eff+(v.m?' (metade)':'')+' = '+through+(v.a&&v.l==='head'&&through>0?' (x2 cabeça)':'')+(bonus?' + 5 (Critical Injury)':'')+'. HP '+old+' → '+c.vidaAtual+(abl?'. Armadura perdeu '+abl+' de SP':''),note:v.c?'Role 2d6 na tabela de Critical Injury ('+(v.l==='head'?'cabeça':'corpo')+').':''})}

